/**
 * Slingshot input / aim / launch UX (plan Step 2).
 *
 * Drag vector -> launch velocity mapping: velocity = (pivot - dragPoint) * POWER_MULT,
 * clamped so the pull distance never exceeds MAX_PULL (caps max power).
 * A pull shorter than MIN_PULL on release is treated as a cancelled aim
 * (bird snaps back, no shot fired) — the plan's "당김 취소 규칙".
 *
 * The trajectory preview line is generated by stepping the exact same
 * recurrence the physics body will experience (gravity applied once per
 * fixed step, zero air friction on the bird) so the dotted preview and
 * the real flight path coincide.
 */
window.Slingshot = (function () {
  const MAX_PULL = 140;
  const MIN_PULL = 15;
  const POWER_MULT = 0.22;
  const GHOST_STEPS = 60;
  const GHOST_STRIDE = 3;

  let canvas = null;
  let enabled = false;
  let dragging = false;
  let dragPoint = null; // {x,y} in logical canvas coords
  let trajectoryPoints = [];
  let onLaunch = null; // (vx, vy) => void

  function toLogical(clientX, clientY) {
    const rect = canvas.getBoundingClientRect();
    const C = window.GAME_CONSTANTS;
    return {
      x: ((clientX - rect.left) / rect.width) * C.CANVAS_W,
      y: ((clientY - rect.top) / rect.height) * C.CANVAS_H
    };
  }

  function clampToPullRadius(point) {
    const C = window.GAME_CONSTANTS;
    const pivot = { x: C.SLING_X, y: C.SLING_Y };
    const dx = point.x - pivot.x;
    const dy = point.y - pivot.y;
    const dist = Math.hypot(dx, dy);
    if (dist <= MAX_PULL) return point;
    const scale = MAX_PULL / dist;
    return { x: pivot.x + dx * scale, y: pivot.y + dy * scale };
  }

  function gravityStepDelta() {
    const g = window.Physics.world.gravity;
    const dt = window.Physics.FIXED_DT;
    return g.y * g.scale * dt * dt;
  }

  function computeLaunchVelocity(point) {
    const C = window.GAME_CONSTANTS;
    const vx = (C.SLING_X - point.x) * POWER_MULT;
    const vy = (C.SLING_Y - point.y) * POWER_MULT;
    return { vx, vy };
  }

  function buildTrajectoryPreview(point) {
    const C = window.GAME_CONSTANTS;
    const { vx, vy } = computeLaunchVelocity(point);
    const gStep = gravityStepDelta();
    let x = C.SLING_X, y = C.SLING_Y, curVx = vx, curVy = vy;
    const pts = [];
    for (let i = 1; i <= GHOST_STEPS; i++) {
      curVy += gStep;
      x += curVx;
      y += curVy;
      if (i % GHOST_STRIDE === 0) pts.push({ x, y });
      if (y > C.GROUND_Y || x > C.CANVAS_W || x < 0) break;
    }
    return pts;
  }

  function onPointerDown(e) {
    if (!enabled) return;
    const p = toLogical(e.clientX, e.clientY);
    const bird = window.Physics.bird;
    if (!bird) return;
    const grabR = window.GAME_CONSTANTS.BIRD_R + 20;
    if (Math.hypot(p.x - bird.position.x, p.y - bird.position.y) > grabR) return;
    dragging = true;
    dragPoint = clampToPullRadius(p);
    Matter.Body.setPosition(bird, dragPoint);
    trajectoryPoints = buildTrajectoryPreview(dragPoint);
    canvas.setPointerCapture && e.pointerId !== undefined && canvas.setPointerCapture(e.pointerId);
  }

  function onPointerMove(e) {
    if (!dragging) return;
    const p = toLogical(e.clientX, e.clientY);
    dragPoint = clampToPullRadius(p);
    const bird = window.Physics.bird;
    if (bird) Matter.Body.setPosition(bird, dragPoint);
    trajectoryPoints = buildTrajectoryPreview(dragPoint);
  }

  function onPointerUp() {
    if (!dragging) return;
    dragging = false;
    const C = window.GAME_CONSTANTS;
    const pullDist = Math.hypot(dragPoint.x - C.SLING_X, dragPoint.y - C.SLING_Y);
    const bird = window.Physics.bird;
    trajectoryPoints = [];

    if (pullDist < MIN_PULL) {
      // cancelled aim: snap the bird back to rest, no shot fired
      if (bird) Matter.Body.setPosition(bird, { x: C.SLING_X, y: C.SLING_Y });
      dragPoint = null;
      return;
    }

    const { vx, vy } = computeLaunchVelocity(dragPoint);
    dragPoint = null;
    if (onLaunch) onLaunch(vx, vy);
  }

  function init(canvasEl, launchCallback) {
    canvas = canvasEl;
    onLaunch = launchCallback;
    canvas.addEventListener('pointerdown', onPointerDown);
    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);
  }

  function setEnabled(v) {
    enabled = v;
    if (!v && dragging) {
      // interaction was interrupted (e.g. pause mid-drag): cancel cleanly
      dragging = false;
      const bird = window.Physics.bird;
      if (bird) Matter.Body.setPosition(bird, { x: window.GAME_CONSTANTS.SLING_X, y: window.GAME_CONSTANTS.SLING_Y });
      dragPoint = null;
      trajectoryPoints = [];
    }
  }

  return {
    init, setEnabled,
    isDragging: () => dragging,
    get dragPoint() { return dragPoint; },
    get trajectoryPoints() { return trajectoryPoints; },
    MAX_PULL,
    POWER_MULT
  };
})();
